sysauto_script.script:
try {
    var r = new sn_ws.RESTMessageV2('x_cdltd_capstone_0.CAP 2.1 Rest Message', 'Default GET');
    r.setStringParameterNoEscape('location', 'Seattle');

    var companyGR = new GlideRecord('core_company');
    // ACME Australia
    companyGR.get('df7d53303710200044e0bfc8bcbe5dac');
    var city = companyGR.city;

    gs.info('CAP 4.1: Fetching weather data for ' + city);

    var response = r.execute();
    var responseBody = JSON.parse(response.getBody());
    var httpStatus = response.getStatusCode();

    if (httpStatus == 200) {
        gs.info('CAP 4.1: Fetching weather data successful');

        var weatherDataGR = new GlideRecord('x_cdltd_capstone_0_weather_data');

		var gdt = new GlideDateTime();
		gdt.setNumericValue(responseBody.current.last_updated_epoch * 1000);

        weatherDataGR.initialize();
		weatherDataGR.observed_at = gdt;
		weatherDataGR.city = responseBody.location.name;
		weatherDataGR.condition = responseBody.current.condition.text;
		weatherDataGR.humidity = responseBody.current.humidity;
		weatherDataGR.temperature_c = responseBody.current.temp_c;
		weatherDataGR.wind_speed = responseBody.current.wind_kph;
		weatherDataGR.insert();

		gs.info('CAP 4.1: Inserting weather data successful');
    }
} catch (ex) {
    var message = ex.message;
	gs.info('CAP 4.1: Error: ' + message);
}
